import React from 'react';

interface TextProps<E extends React.ElementType = 'span'> {
  as?: E;
  children: React.ReactNode;
  className?: string;
}

type TextComponent = <E extends React.ElementType = 'span'>(
  props: TextProps<E> & Omit<React.ComponentProps<E>, keyof TextProps<E>>
) => React.ReactElement | null;

const Text: TextComponent = ({ as, children, className, ...rest }) => {
  const Component = as || 'span';
  return (
    <Component className={`text ${className || ''}`} {...rest}>
      {children}
    </Component>
  );
};

// Usage
<Text as="p" className="lead">
  This renders as a paragraph.
</Text>
<Text as="a" href="#" className="link">
  This renders as a link.
</Text>
<Text as="label" htmlFor="email">
  This renders as a label.
</Text>

type ButtonProps<E extends React.ElementType = 'button'> = {
  as?: E;
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
  children: React.ReactNode;
  className?: string;
} & Omit<React.ComponentProps<E>, keyof ButtonProps<E>>;

function Button<E extends React.ElementType = 'button'>({
  as,
  variant = 'primary',
  size = 'md',
  isLoading = false,
  children,
  className,
  ...rest
}: ButtonProps<E>) {
  const Component = as || 'button';

  const classes = [
    'btn',
    `btn-${variant}`,
    `btn-${size}`,
    isLoading ? 'btn-loading' : '',
    className || '',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <Component className={classes} disabled={isLoading || (rest as { disabled?: boolean }).disabled} {...rest}>
      {isLoading && <span className="spinner" aria-hidden="true" />}
      {children}
    </Component>
  );
}

// Usage
<Button variant="primary" size="lg" onClick={handleClick}>
  Submit
</Button>

<Button as="a" href="/login" variant="secondary">
  Sign In
</Button>

<Button as={Link} to="/dashboard" variant="ghost">
  Dashboard
</Button>

import React from 'react';

type PolymorphicProps<E extends React.ElementType = 'button'> = {
  as?: E;
  children: React.ReactNode;
} & Omit<React.ComponentProps<E>, keyof PolymorphicProps<E>>;

function PolymorphicComponent<E extends React.ElementType = 'button'>(
  { as, children, ...rest }: PolymorphicProps<E>,
  ref: React.Ref<React.ElementType<E>>
) {
  const Component = as || 'button';
  return (
    <Component ref={ref} {...rest}>
      {children}
    </Component>
  );
}

const ForwardedPolymorphic = React.forwardRef(
  PolymorphicComponent
) as <E extends React.ElementType = 'button'>(
  props: PolymorphicProps<E> & { ref?: React.Ref<React.ElementType<E>> }
) => React.ReactElement | null;

// Usage with ref
const btnRef = React.useRef<HTMLButtonElement>(null);

<ForwardedPolymorphic ref={btnRef} variant="primary">
  Click me
</ForwardedPolymorphic>

<ForwardedPolymorphic as="a" href="#" ref={btnRef as React.Ref<HTMLAnchorElement>}>
  Link
</ForwardedPolymorphic>
